INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES (944, 0, "はい、そこの流れてくるおねーさん\nたい焼きいかがかにゃ？", 1, 107911, 0, 1, 8, 11, 19440025, 0);
INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES (944, "", "", "", 0, "", "", "", 91, 19440026, "");
