INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES (944, 0.2, "cmn_boat_idle", "", 2, "", "", 1, 3, 19440028, "");
INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES (944, "", "vo_fpc_30403", 0, "vo_fpc", "", "", "", 21, 19440029, "");
INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES (944, 0, "あら、タマキさんじゃない。\nこんなところで何やってるの？", 1, 126811, 0, 1, 10, 11, 19440030, 0);
INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES (944, "", "", "", 0, "", "", "", 91, 19440031, "");
INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES (944, "", "vo_fpc_30404", 0, "vo_fpc", "", "", "", 21, 19440032, "");
INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES (944, 0, "なんだ、ユカリだったかにゃ。\n何ってもちろん商売にゃ！", 1, 107911, 0, 1, 10, 11, 19440033, 0);
INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES (944, "", "", "", 0, "", "", "", 91, 19440034, "");
