INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES (944, 0, "それ、アキノさんの許可とってるの？\nもし無許可だったら怒られるわよ？", 1, 126811, 0, 1, 7, 11, 19440043, 0);
INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES (944, "", "", "", 0, "", "", "", 91, 19440044, "");
