INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES (944, 0, "大丈夫にゃ。バレないように…\nってやばいにゃ！　見回りだにゃ！", 1, 107911, 0, 0.5, 8, 11, 19440046, 0);
INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES (944, "", "", "", 0, "", "", "", 91, 19440047, "");
