INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES (945, 0, "どうしたんだ、ユイ？\nあいつのために\nわざわざ弁当作ってきたんだろ？\nとっとと誘えばいいじゃないか。", 1, 110411, 0, 1, 10, 11, 19450021, 0);
INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES (945, "", "", "", 0, "", "", "", 91, 19450022, "");
INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES (945, "", "vo_fpc_30502", 0, "vo_fpc", "", "", "", 21, 19450023, "");
INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES (945, 0, "買い出しまで手伝ってもらったのに\nごめんね。でも、お弁当の中身、\nちょっと張り切りすぎちゃって…", 1, 122611, 0, 1, 7, 11, 19450024, 0);
INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES (945, "", "", "", 0, "", "", "", 91, 19450025, "");
